import type { TargetSummary, TargetTransport } from "../shared/target-contracts.js";

/** Pinned command-tree source and runtime assessment; no renderer or IPC import. */
export const BEACON_COMMAND_BASELINE_COMMIT = "f8430cecf7ceb5cb332c84fb36aba9b75188802d" as const;

export type BeaconCommandMilestone = "M1" | "M2" | "M4" | "M5" | "M8";
export type BeaconCommandPlatform = "windows" | "linux" | "darwin";
export type BeaconCommandDelivery = "existing" | "planned" | "deferred";
export type BeaconCommandSupport = "source-confirmed" | "pending-runtime" | "session-only" | "operator-only" | "navigation-only" | "unsupported";
export type BeaconResponsePolicy = "none" | "current-preview" | "current-execution" | "proposed-bounded-fetch" | "proposed-native-artifact";
export type BeaconEffectProof = "direct-result" | "requires-requery" | "unverifiable";

export const PINNED_COMPILER_TARGET_ARCHITECTURES = Object.freeze({
  windows: Object.freeze(["386", "amd64", "arm64"] as const),
  linux: Object.freeze(["386", "amd64", "arm64"] as const),
  darwin: Object.freeze(["amd64", "arm64"] as const),
} as const); // server/generate/binaries.go at the pinned baseline.

export const BEACON_RESPONSE_CEILINGS = Object.freeze({
  none: 0,
  "current-preview": 64 * 1_024,
  "current-execution": (2 * 1_024 * 1_024) + (64 * 1_024),
  "proposed-bounded-fetch": 1 * 1_024 * 1_024,
  "proposed-native-artifact": 64 * 1_024 * 1_024,
  /** Upload input bytes are a separate proposed main-owned request limit. */
  proposedUploadInputBytes: 64 * 1_024 * 1_024,
} as const);

export interface BeaconRpcStep {
  readonly rpcMethod: string;
  /** The queued protobuf payload type (usually also BeaconTask.Description). */
  readonly requestType: string;
  /** Server RPC input when it transforms a different request into the queued type. */
  readonly rpcRequestType?: string;
  /** Server RPC return type; it need not be a fetched beacon task result (Kill is special). */
  readonly responseType: string;
  readonly taskResponseType?: "none";
  readonly taskDescription: string;
}
export type BeaconCommandRoute =
  | { readonly kind: "task"; readonly steps: readonly BeaconRpcStep[]; readonly responsePolicy: BeaconResponsePolicy; readonly maximumResponseBytes: number; readonly effectProof: BeaconEffectProof }
  | { readonly kind: "existing-execution"; readonly executionOperationId: string; readonly task: Extract<BeaconCommandRoute, { kind: "task" }> }
  | { readonly kind: "existing-main"; readonly operationId: string; readonly task?: Extract<BeaconCommandRoute, { kind: "task" }> }
  | { readonly kind: "metadata"; readonly fields: readonly string[] }
  | { readonly kind: "hybrid"; readonly fields: readonly string[]; readonly windowsSteps: readonly BeaconRpcStep[]; readonly responsePolicy: "proposed-bounded-fetch"; readonly maximumResponseBytes: number }
  | { readonly kind: "navigation"; readonly reason: string }
  | { readonly kind: "operator-workflow"; readonly reason: string }
  | { readonly kind: "deferred-workflow"; readonly reason: string };

export interface BeaconProtocolStep {
  readonly rpcMethod: string;
  readonly rpcRequestType: string;
  readonly rpcResponseType: string;
}

export interface BeaconCommandDescriptor {
  /** RPC protocol identity, including deferred workflows; never a dispatch table. */
  readonly protocol: readonly BeaconProtocolStep[];
  readonly milestone: BeaconCommandMilestone;
  readonly delivery: BeaconCommandDelivery;
  readonly support: BeaconCommandSupport;
  readonly platforms: readonly BeaconCommandPlatform[];
  /** Effective per-platform build targets at the pinned baseline. */
  readonly architecturesByPlatform: Readonly<Partial<typeof PINNED_COMPILER_TARGET_ARCHITECTURES>>;
  readonly transports: readonly TargetTransport[];
  readonly source: Readonly<{ file: string; line: number }>;
  readonly runtimeEvidence: readonly string[];
  /** Standard beacon transports are source candidates; pivot variants remain withheld pending proof. */
  readonly transportReview: string;
  readonly consoleOptions: readonly string[];
  /** Each reviewed console option appears in exactly one boundary bucket. */
  readonly optionBoundary: Readonly<{ request: readonly string[]; local: readonly string[]; main: readonly string[]; pending: readonly string[] }>;
  readonly route: BeaconCommandRoute;
}

const COMMON_BEACON_TRANSPORTS = Object.freeze(["mtls", "http", "https", "dns", "wg"] as const);
const WG_TRANSPORT = Object.freeze(["wg"] as const);

function task(steps: readonly BeaconRpcStep[], responsePolicy: BeaconResponsePolicy, effectProof: BeaconEffectProof): Extract<BeaconCommandRoute, { kind: "task" }> {
  return { kind: "task", steps, responsePolicy, maximumResponseBytes: BEACON_RESPONSE_CEILINGS[responsePolicy], effectProof };
}
function executionTask(executionOperationId: string, taskRoute: Extract<BeaconCommandRoute, { kind: "task" }>): BeaconCommandRoute {
  return { kind: "existing-execution", executionOperationId, task: taskRoute };
}
function existingMain(operationId: string, taskRoute?: Extract<BeaconCommandRoute, { kind: "task" }>): BeaconCommandRoute {
  return taskRoute ? { kind: "existing-main", operationId, task: taskRoute } : { kind: "existing-main", operationId };
}
function metadata(fields: readonly string[]): BeaconCommandRoute { return { kind: "metadata", fields }; }
function hybrid(fields: readonly string[], windowsSteps: readonly BeaconRpcStep[]): BeaconCommandRoute {
  return { kind: "hybrid", fields, windowsSteps, responsePolicy: "proposed-bounded-fetch", maximumResponseBytes: BEACON_RESPONSE_CEILINGS["proposed-bounded-fetch"] };
}
function navigation(reason: string): BeaconCommandRoute { return { kind: "navigation", reason }; }
function operatorWorkflow(reason: string): BeaconCommandRoute { return { kind: "operator-workflow", reason }; }
function deferred(reason: string): BeaconCommandRoute { return { kind: "deferred-workflow", reason }; }

function descriptor(
  milestone: BeaconCommandMilestone, delivery: BeaconCommandDelivery, support: BeaconCommandSupport,
  platforms: readonly BeaconCommandPlatform[], source: BeaconCommandDescriptor["source"],
  runtimeEvidence: readonly string[], consoleOptions: readonly string[], optionBoundary: BeaconCommandDescriptor["optionBoundary"],
  route: BeaconCommandRoute, protocol: readonly BeaconProtocolStep[], transports: readonly TargetTransport[] = COMMON_BEACON_TRANSPORTS,
): BeaconCommandDescriptor {
  const architecturesByPlatform = Object.fromEntries(
    platforms.map((platform) => [platform, PINNED_COMPILER_TARGET_ARCHITECTURES[platform]]),
  ) as BeaconCommandDescriptor["architecturesByPlatform"];
  return { protocol, milestone, delivery, support, platforms, architecturesByPlatform, transports, source, runtimeEvidence, transportReview: "Pinned command tree says any; named-pipe and TCP-pivot beacon transport paths remain withheld pending runtime proof.", consoleOptions, optionBoundary, route };
}

