export type BeaconCommandId = keyof typeof BEACON_COMMAND_MATRIX;
export type BeaconCommandAvailabilityReason = "unknown-command" | "requires-beacon" | "not-delivered" | "unverified-runtime" | "unsupported-platform" | "unsupported-architecture" | "unsupported-transport" | "non-task-route";
export type BeaconCommandAvailability = { readonly available: true } | { readonly available: false; readonly reason: BeaconCommandAvailabilityReason };

/** Source-matrix gate only. Dispatch still requires the existing exact-target, server-support, and operation-review checks. */
export function beaconCommandCapability(id: string, target: TargetSummary): BeaconCommandAvailability {
  if (!Object.hasOwn(BEACON_COMMAND_MATRIX, id)) return { available: false, reason: "unknown-command" };
  const row = BEACON_COMMAND_MATRIX[id as BeaconCommandId];
  if (target.mode !== "beacon") return { available: false, reason: "requires-beacon" };
  if (row.delivery !== "existing") return { available: false, reason: "not-delivered" };
  if (row.support !== "source-confirmed") return { available: false, reason: "unverified-runtime" };
  if (!row.platforms.includes(target.os.trim().toLowerCase() as BeaconCommandPlatform)) return { available: false, reason: "unsupported-platform" };
  const platform = target.os.trim().toLowerCase() as BeaconCommandPlatform;
  const architecture = target.arch.trim().toLowerCase() as "386" | "amd64" | "arm64";
  if (!row.architecturesByPlatform[platform]?.includes(architecture as never)) {
    return { available: false, reason: "unsupported-architecture" };
  }
  if (!row.transports.includes(target.transport)) return { available: false, reason: "unsupported-transport" };
  if (row.route.kind === "navigation" || row.route.kind === "operator-workflow" || row.route.kind === "deferred-workflow") {
    return { available: false, reason: "non-task-route" };
  }
  return { available: true };
}

function deepFreeze<Value>(value: Value): Value {
  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}
